<?php
$pageTitle='Dashboard';
require_once __DIR__.'/includes/header.php';
require_once __DIR__.'/includes/sidebar.php';
$db=getDB();$club=$_SESSION['club_id'];
$today=$db->prepare("SELECT COALESCE(SUM(total_amount),0) FROM sessions WHERE club_id=? AND status='completed' AND DATE(end_time)=CURDATE()");$today->execute([$club]);$revenue=(float)$today->fetchColumn();
$active=$db->prepare("SELECT COUNT(*) FROM sessions WHERE club_id=? AND status IN ('running','paused')");$active->execute([$club]);$activeSessions=(int)$active->fetchColumn();
$expensesQ=$db->prepare('SELECT COALESCE(SUM(amount),0) FROM expenses WHERE club_id=? AND expense_date=CURDATE()');$expensesQ->execute([$club]);$expenses=(float)$expensesQ->fetchColumn();
$playersQ=$db->prepare('SELECT COUNT(*) FROM players WHERE club_id=? AND is_active=1');$playersQ->execute([$club]);$players=(int)$playersQ->fetchColumn();
$month=$db->prepare("SELECT COALESCE(SUM(total_amount),0) FROM sessions WHERE club_id=? AND status='completed' AND DATE_FORMAT(end_time,'%Y-%m')=DATE_FORMAT(CURDATE(),'%Y-%m')");$month->execute([$club]);$monthly=(float)$month->fetchColumn();
$cafeQ=$db->prepare("SELECT COALESCE(SUM(total_amount),0) FROM cafe_orders WHERE club_id=? AND status='completed' AND DATE(created_at)=CURDATE()");$cafeQ->execute([$club]);$cafe=(float)$cafeQ->fetchColumn();
$tableQ=$db->prepare("SELECT status,COUNT(*) count FROM tables WHERE club_id=? AND is_active=1 GROUP BY status");$tableQ->execute([$club]);$floor=[];foreach($tableQ as $row)$floor[$row['status']]=(int)$row['count'];$available=$floor['available']??0;$paused=$floor['paused']??0;$held=$floor['held']??0;
$daily=$db->prepare("SELECT DATE(end_time) d,SUM(total_amount) total FROM sessions WHERE club_id=? AND status='completed' AND end_time >= DATE_SUB(CURDATE(), INTERVAL 30 DAY) GROUP BY DATE(end_time) ORDER BY d");$daily->execute([$club]);$chart=$daily->fetchAll();
?>
