<div class="grid md:grid-cols-3 gap-4 mt-4"><article class="dashboard-secondary"><span class="metric-label">Month-to-date revenue</span><p><?=money($monthly)?></p><small>Completed session revenue</small></article><article class="dashboard-secondary"><span class="metric-label">Active players</span><p><?=$players?></p><small>Members and regular guests</small></article><article class="dashboard-secondary"><span class="metric-label">Café sales today</span><p><?=money($cafe)?></p><small>Completed café orders</small></article></div>
<div class="grid xl:grid-cols-5 gap-4 mt-5"><section class="dashboard-panel xl:col-span-3"><div class="panel-head"><div><h2 class="section-title">Revenue performance</h2><p class="section-subtitle">Daily completed session revenue for the last 30 days.</p></div><span class="soft-pill">30 days</span></div><div class="h-64"><canvas id="revenueChart"></canvas></div></section><section class="dashboard-panel xl:col-span-2"><div class="panel-head"><div><h2 class="section-title">Sales breakdown</h2><p class="section-subtitle">Table sessions and café orders recorded today.</p></div></div><div class="h-64"><canvas id="sourceChart"></canvas></div></section></div>
